import sys
from math import ceil

def min_rolls_to_target(target):
    # The minimum number of rolls needed is the ceiling of target divided by 7
    return ceil(target / 7)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []

    index = 1
    for _ in range(t):
        x = int(data[index])
        results.append(min_rolls_to_target(x))
        index += 1

    for result in results:
        print(result)

if __name__ == "__main__":
    main()

